def simulate_bacteria(N, M, K, trap_row, trap_col, bacteria):
    directions = {'U': (-1, 0), 'R': (0, 1), 'D': (1, 0), 'L': (0, -1)}
    opposite_directions = {'U': 'D', 'R': 'L', 'D': 'U', 'L': 'R'}

    def turn_clockwise(direction, times):
        clockwise_order = ['U', 'R', 'D', 'L']
        current_index = clockwise_order.index(direction)
        new_index = (current_index + times) % 4
        return clockwise_order[new_index]

    def move_bacterium(bacterium, grid):
        x, y, direction = bacterium
        X = grid[x-1][y-1]
        direction = turn_clockwise(direction, X)

        dx, dy = directions[direction]
        nx, ny = x + dx, y + dy

        if not (1 <= nx <= N and 1 <= ny <= M):
            direction = opposite_directions[direction]
            dx, dy = directions[direction]
            nx, ny = x + dx, y + dy

        return (nx, ny, direction)

    def find_cycle(bacteria, grids):
        visited = [set() for _ in range(K)]
        steps = [0] * K

        while True:
            for i in range(K):
                bacterium = bacteria[i]
                grid = grids[i]
                new_bacterium = move_bacterium(bacterium, grid)
                bacteria[i] = new_bacterium

                if new_bacterium in visited[i]:
                    return -1
                visited[i].add(new_bacterium)

                if new_bacterium[:2] == (trap_row, trap_col):
                    steps[i] += 1

            if all(steps[i] == steps[0] for i in range(1, K)):
                return steps[0]

            for i in range(K):
                steps[i] += 1

    grids = []
    for i in range(K):
        grid = [list(map(int, input().split())) for _ in range(N)]
        grids.append(grid)

    bacteria = [(int(x), int(y), C) for x, y, C in bacteria]

    return find_cycle(bacteria, grids)

